import type { Readable } from "node:stream";
import type { BackupDestinationKind, S3DestinationSettings, SftpDestinationSettings } from "@nebuladb/shared";

/**
 * Where a backup's bytes go. What reaches a store is already gzipped and
 * encrypted by `storage.ts` — a store only moves opaque bytes, so the remote
 * never sees plain data. `name` is always `<backup id>.bak`, generated by the
 * server.
 */
export interface BackupStore {
  readonly kind: BackupDestinationKind;
  /**
   * Streams `source` to the object `name`. Resolves once it is stored whole;
   * if `source` errors or is destroyed, or the transfer fails, nothing is left
   * behind (the multipart upload is aborted, the partial file removed) and it
   * rejects.
   */
  write(name: string, source: Readable): Promise<void>;
  /** The object's bytes. Rejects with `ObjectMissingError` when there is none, with the remote's own error when it cannot be reached. */
  read(name: string): Promise<Readable>;
  /** Removes the object; one that is already gone is not an error. */
  delete(name: string): Promise<void>;
  /** Writes, reads back and deletes a probe object; throws the remote's own error. */
  probe(): Promise<void>;
}

export class ObjectMissingError extends Error {
  constructor(name: string) {
    super(`${name} is not there`);
  }
}

/** What is kept encrypted for a remote: the credentials. */
export interface S3Secret {
  accessKeyId: string;
  secretAccessKey: string;
}

export interface SftpSecret {
  password?: string;
  privateKey?: string;
  passphrase?: string;
}

export type RemoteDestination =
  | { kind: "s3"; settings: S3DestinationSettings; secret: S3Secret }
  | { kind: "sftp"; settings: SftpDestinationSettings; secret: SftpSecret };
